mapper.select:
SELECT orderno, session_id, email, seat, status, expires_at
FROM interviewworks_ticket.ticket
WHERE orderno = #{orderno}

mapper.update:
UPDATE interviewworks_ticket.session_seat
SET status            = #{status},
    reserved_by_order = CASE WHEN #{status} = 'SOLD' THEN #{orderno} ELSE NULL END,
    reserved_until    = NULL,
    version           = version + 1
WHERE session_id = #{sessionId}
  AND seat_id = #{seat}
  AND reserved_by_order = #{orderno}
  AND status = 'RESERVED'

mapper.select:
SELECT request_hash, orderno, response_body
FROM interviewworks_ticket.booking_idempotency
WHERE email = #{email}
  AND idempotency_key = #{idempotencyKey}
FOR UPDATE

mapper.update:
UPDATE interviewworks_ticket.booking_idempotency
SET orderno       = #{createdOrderNo},
    response_body = #{body}
WHERE email = #{email}
  AND idempotency_key = #{idempotencyKey}
  AND orderno IS NULL
